/* khrt_tables.h : tables generated by tools/genrt.py (kh_table.c) and consumed by khrt_dispatch.c */
#pragma once
#include "khrt.h"
typedef void (*KhFn)(KCtx *);
typedef struct { u32 rva; KhFn fn; } KhFnEnt;                       /* every universe function start (lifted, hook or .nep stub), ascending rva */
typedef struct { u32 slot_rva; KhFn fn; const char *dll; const char *name; } KhImportEnt;   /* every PE import; slot_rva = IAT slot */
extern const KhFnEnt kh_fn_table[]; extern const u32 kh_fn_count;
extern const KhImportEnt kh_import_table[]; extern const u32 kh_import_count;
/* default synthetic guest address of import #i (the loader stores it in the IAT slot; configurable at run time) */
extern u64 kh_import_addr_base;
#define KH_IMPORT_ADDR_BASE_DEFAULT 0x7ff7f0000000ull
void kh_unimplemented_import(KCtx *g, const char *dll, const char *name) __attribute__((noreturn));
void kh_nep_stub(KCtx *g, u32 rva);
